const rows = csv(files['sales.csv'])
const total = {}
for (const r of rows) { const m = r.date.slice(0, 7); total[m] = (total[m] || 0) + r.amount }
const months = Object.keys(total).sort()
chart({ type: 'bar', title: 'Sales by month ($)', labels: months, series: [{ name: 'Total', values: months.map((m) => total[m]) }] })
return total
